    const q = new AsyncQueue<string>();
    q.enqueue("fail", { maxAttempts: 5 });
    let calls = 0;
    const handler = () => { calls++; throw new Error("boom"); };

    for (let i = 1; i <= 5; i++) {
      const job = q.dequeue();
      const r = await q.processJob(job, handler);
      expect(r.success).toBe(false);
      expect(r.job.attempts).toBe(i);
      if (i < 5) {
        expect(q.size()).toBe(1); // re-enqueued for next retry
      }
    }
    expect(q.isEmpty()).toBe(true); // exhausted after 5 attempts
    expect(calls).toBe(5);
  });

  test("handler success on first attempt does NOT re-enqueue", async () => {
    const q = new AsyncQueue<string>();
    q.enqueue("ok");
    const job = q.dequeue();
    const r = await q.processJob(job, async () => {});
    expect(r.success).toBe(true);
    expect(r.job.attempts).toBe(1);
    expect(q.isEmpty()).toBe(true);
  });

  test("handler success after retries does NOT re-enqueue", async () => {
    const q = new AsyncQueue<number>();
    q.enqueue(42, { maxAttempts: 5 });
    let calls = 0;
    const handler = (n: number) => {
      calls++;
      if (calls < 3) throw new Error("not yet");
    };

    const r = await q.processNext(handler);
    expect(r!.success).toBe(false);
    expect(r!.job.attempts).toBe(1);

    const r2 = await q.processNext(handler);
    expect(r2!.success).toBe(false);
    expect(r2!.job.attempts).toBe(2);

    const r3 = await q.processNext(handler);
    expect(r3!.success).toBe(true);
    expect(r3!.job.attempts).toBe(3);
    expect(q.isEmpty()).toBe(true);
  });

  test("processJob returns correct job id", async () => {
    const q = new AsyncQueue<string>();
