  test("processJob returns correct job id", async () => {
    const q = new AsyncQueue<string>();
    const enqueued = q.enqueue("data", { id: "my-job" });
    const job = q.dequeue();
    const r = await q.processJob(job, () => { throw new Error("x"); });
    expect(r.job.id).toBe("my-job");
  });

  test("attempts counter increments correctly across retries", async () => {
    const q = new AsyncQueue<string>();
    q.enqueue("x", { maxAttempts: 3 });
    const handler = () => { throw new Error("fail"); };

    const r1 = await q.processNext(handler);
    expect(r1!.job.attempts).toBe(1);

    const r2 = await q.processNext(handler);
    expect(r2!.job.attempts).toBe(2);

    const r3 = await q.processNext(handler);
    expect(r3!.job.attempts).toBe(3);

    expect(q.isEmpty()).toBe(true);
  });

  test("concurrent processJob calls maintain invariants", async () => {
    const q = new AsyncQueue<number>({ concurrency: 3 });
    for (let i = 0; i < 10; i++) q.enqueue(i);

    const jobs: Promise<{ success: boolean }>[] = [];
    while (!q.isEmpty()) {
      const job = q.dequeue();
      jobs.push(q.processJob(job, async (n) => {
        if (n % 2 === 0) throw new Error("even");
      }));
    }

    const results = await Promise.all(jobs);
    // All should report correctly
    const successes = results.filter(r => r.success);
    const failures = results.filter(r => !r.success);
    expect(successes.length).toBe(5); // odds succeed
    expect(failures.length).toBe(5);  // evens fail
    // Queue should be empty since all jobs reached maxAttempts=3 by processing once
    // and the re-enqueued jobs are not being processed in this test
  });

  test("empty queue processNext returns null", async () => {
    const q = new AsyncQueue<string>();
    expect(await q.processNext(() => {})).toBeNull();
  });

  test("clear removes re-enqueued jobs from retries", async () => {
    const q = new AsyncQueue<string>();
    q.enqueue("fail", { maxAttempts: 3 });
    const job = q.dequeue();
    await q.processJob(job, () => { throw new Error("boom"); });
    expect(q.size()).toBe(1); // re-enqueued
    q.clear();
    expect(q.isEmpty()).toBe(true);
  });
});

